// Dois itens de exemplo — um selo, um termômetro. Edite à vontade para testar.
return [
  { json: { template: 'selo-hype', data: {
    titulo: 'Modelo de IA promete diagnosticar doenças, mas estudo ainda é preliminar',
    nota_hype: 8,
    nota_realidade: 4,
  } } },
  { json: { template: 'termometro', data: {
    indice: 62,
    semana: 'Semana de 9 a 13 de junho',
  } } },
];

// Browserless self-hosted (definido no build via BROWSERLESS_URL/BROWSERLESS_TOKEN; ver scripts/build-render-imagens.mjs).
const BROWSERLESS = "http://browserless:3000";
const TOKEN = "";

const TEMPLATES = {
  'selo-hype': "<!doctype html>
<!--
  Template: Selo Hype vs. Realidade — 1080×1350 (Instagram 4:5)
  Placeholders (injetados pelo n8n antes do render):
    {{titulo}}         título da notícia (máx ~80 chars; acima disso a fonte reduz via CSS)
    {{nota_hype}}      inteiro 0-10
    {{nota_realidade}} inteiro 0-10
  Render (T07): Puppeteer/Browserless — viewport 1080×1350, deviceScaleFactor 1,
  aguardar networkidle0 (fontes do Google), screenshot do body.
-->
<html lang="pt-BR">
<head>
<meta charset="utf-8">
<link href="https://fonts.googleapis.com/css2?family=Bebas+Neue&family=Archivo:wght@400;600&display=swap" rel="stylesheet">
<style>
  * { margin: 0; padding: 0; box-sizing: border-box; }
  html, body { width: 1080px; height: 1350px; overflow: hidden; }
  body {
    background: #0A0A0A;
    color: #FFFFFF;
    font-family: 'Archivo', 'Helvetica Neue', Arial, sans-serif;
    position: relative;
    display: flex;
    flex-direction: column;
    padding: 72px 80px 64px;
  }
  /* grade geométrica sutil (identidade do site) */
  body::before {
    content: '';
    position: absolute; inset: 0;
    background-image:
      linear-gradient(rgba(255,230,0,0.05) 1px, transparent 1px),
      linear-gradient(90deg, rgba(255,230,0,0.05) 1px, transparent 1px);
    background-size: 90px 90px;
    pointer-events: none;
  }
  .brand {
    font-family: 'Bebas Neue', sans-serif;
    font-size: 44px;
    letter-spacing: 6px;
    color: #FFE600;
  }
  .quadro {
    margin-top: 10px;
    font-size: 24px;
    letter-spacing: 4px;
    text-transform: uppercase;
    color: rgba(255,255,255,0.55);
  }
  .titulo {
    margin-top: 80px;
    font-family: 'Bebas Neue', sans-serif;
    font-size: 76px;
    line-height: 1.15;
    text-transform: uppercase;
    display: -webkit-box;
    -webkit-line-clamp: 4;
    -webkit-box-orient: vertical;
    overflow: hidden;
  }
  .medidores { margin-top: auto; }
  .medidor { margin-top: 56px; }
  .medidor .rotulo {
    display: flex;
    justify-content: space-between;
    align-items: baseline;
    margin-bottom: 18px;
  }
  .medidor .nome {
    font-family: 'Bebas Neue', sans-serif;
    font-size: 52px;
    letter-spacing: 3px;
  }
  .medidor .valor {
    font-family: 'Bebas Neue', sans-serif;
    font-size: 72px;
  }
  .medidor .valor small { font-size: 36px; color: rgba(255,255,255,0.45); }
  .trilho {
    height: 36px;
    background: rgba(255,255,255,0.10);
    border: 1px solid rgba(255,255,255,0.18);
  }
  .barra { height: 100%; }
  .hype  .nome, .hype .valor  { color: #FF4D4D; }
  .hype  .barra { width: calc({{nota_hype}} * 10%); background: #FF4D4D; }
  .real  .nome, .real .valor  { color: #FFE600; }
  .real  .barra { width: calc({{nota_realidade}} * 10%); background: #FFE600; }
  .assinatura {
    margin-top: 96px;
    padding-top: 32px;
    border-top: 1px solid rgba(255,230,0,0.35);
    display: flex;
    justify-content: space-between;
    font-size: 24px;
    color: rgba(255,255,255,0.55);
  }
  .assinatura b { color: #FFFFFF; font-weight: 600; }
  /* losango decorativo (assinatura visual do site) */
  .diamond {
    position: absolute; top: 64px; right: 72px;
    width: 72px; height: 72px;
    border: 2px solid rgba(255,230,0,0.5);
    transform: rotate(45deg);
  }
  .diamond::after {
    content: '';
    position: absolute; inset: 14px;
    border: 2px solid rgba(255,230,0,0.25);
  }
</style>
</head>
<body>
  <div class="diamond"></div>
  <div class="brand">IA TRADUZIDA</div>
  <div class="quadro">Hype vs. Realidade</div>

  <h1 class="titulo">{{titulo}}</h1>

  <div class="medidores">
    <div class="medidor hype">
      <div class="rotulo">
        <span class="nome">Hype</span>
        <span class="valor">{{nota_hype}}<small>/10</small></span>
      </div>
      <div class="trilho"><div class="barra"></div></div>
    </div>
    <div class="medidor real">
      <div class="rotulo">
        <span class="nome">Realidade</span>
        <span class="valor">{{nota_realidade}}<small>/10</small></span>
      </div>
      <div class="trilho"><div class="barra"></div></div>
    </div>
  </div>

  <div class="assinatura">
    <span>Escrito por agentes. <b>Auditado por um professor de IA.</b></span>
  </div>
</body>
</html>
",
  'termometro': "<!doctype html>
<!--
  Template: Termômetro da IA — 1080×1350 (Instagram 4:5 / LinkedIn)
  Placeholders (injetados pelo n8n antes do render):
    {{indice}}  inteiro 0-100 (índice de sentimento da semana)
    {{semana}}  rótulo da semana, ex.: "Semana de 8 a 12 de junho"
  Render (T07): Puppeteer/Browserless — viewport 1080×1350, deviceScaleFactor 1,
  aguardar networkidle0, screenshot do body.
  Leitura do índice: 0 = pessimismo total, 50 = neutro, 100 = euforia total.
  Fontes do índice (fixas no rodapé): Bluesky + Reddit + Google Trends BR.
-->
<html lang="pt-BR">
<head>
<meta charset="utf-8">
<link href="https://fonts.googleapis.com/css2?family=Bebas+Neue&family=Archivo:wght@400;600&display=swap" rel="stylesheet">
<style>
  * { margin: 0; padding: 0; box-sizing: border-box; }
  html, body { width: 1080px; height: 1350px; overflow: hidden; }
  body {
    background: #0A0A0A;
    color: #FFFFFF;
    font-family: 'Archivo', 'Helvetica Neue', Arial, sans-serif;
    position: relative;
    display: flex;
    flex-direction: column;
    padding: 72px 80px 64px;
  }
  body::before {
    content: '';
    position: absolute; inset: 0;
    background-image:
      linear-gradient(rgba(255,230,0,0.05) 1px, transparent 1px),
      linear-gradient(90deg, rgba(255,230,0,0.05) 1px, transparent 1px);
    background-size: 90px 90px;
    pointer-events: none;
  }
  .brand {
    font-family: 'Bebas Neue', sans-serif;
    font-size: 44px;
    letter-spacing: 6px;
    color: #FFE600;
  }
  .quadro {
    margin-top: 10px;
    font-size: 24px;
    letter-spacing: 4px;
    text-transform: uppercase;
    color: rgba(255,255,255,0.55);
  }
  .semana {
    margin-top: 6px;
    font-size: 26px;
    color: rgba(255,255,255,0.7);
  }
  .palco {
    flex: 1;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 110px;
    margin: 40px 0;
  }
  /* termômetro */
  .termo { display: flex; flex-direction: column; align-items: center; }
  .tubo {
    width: 120px; height: 620px;
    border: 3px solid rgba(255,255,255,0.25);
    border-radius: 60px 60px 0 0;
    background: rgba(255,255,255,0.06);
    position: relative;
    overflow: hidden;
  }
  .mercurio {
    position: absolute; bottom: 0; left: 0; right: 0;
    height: {{indice}}%;
    background: linear-gradient(to top, #FFE600, #FFB800);
  }
  .bulbo {
    width: 190px; height: 190px;
    border-radius: 50%;
    background: #FFE600;
    margin-top: -24px;
    z-index: 1;
    display: flex; align-items: center; justify-content: center;
    font-family: 'Bebas Neue', sans-serif;
    font-size: 76px;
    color: #0A0A0A;
  }
  /* escala + número gigante */
  .leitura { display: flex; flex-direction: column; justify-content: center; }
  .indice {
    font-family: 'Bebas Neue', sans-serif;
    font-size: 270px;
    line-height: 0.9;
    color: #FFE600;
  }
  .de-100 {
    font-family: 'Bebas Neue', sans-serif;
    font-size: 54px;
    color: rgba(255,255,255,0.45);
    letter-spacing: 2px;
  }
  .escala { margin-top: 56px; font-size: 26px; color: rgba(255,255,255,0.65); line-height: 1.9; }
  .escala span { color: #FFE600; margin-right: 14px; font-family: 'Bebas Neue', sans-serif; font-size: 30px; }
  .assinatura {
    padding-top: 32px;
    border-top: 1px solid rgba(255,230,0,0.35);
    display: flex;
    flex-direction: column;
    gap: 10px;
    font-size: 24px;
    color: rgba(255,255,255,0.55);
  }
  .assinatura b { color: #FFFFFF; font-weight: 600; }
  .fontes { font-size: 21px; color: rgba(255,255,255,0.4); }
  .diamond {
    position: absolute; top: 64px; right: 72px;
    width: 72px; height: 72px;
    border: 2px solid rgba(255,230,0,0.5);
    transform: rotate(45deg);
  }
  .diamond::after {
    content: '';
    position: absolute; inset: 14px;
    border: 2px solid rgba(255,230,0,0.25);
  }
</style>
</head>
<body>
  <div class="diamond"></div>
  <div class="brand">IA TRADUZIDA</div>
  <div class="quadro">Termômetro da IA</div>
  <div class="semana">{{semana}}</div>

  <div class="palco">
    <div class="termo">
      <div class="tubo"><div class="mercurio"></div></div>
      <div class="bulbo">{{indice}}</div>
    </div>
    <div class="leitura">
      <div class="indice">{{indice}}</div>
      <div class="de-100">DE 0 A 100</div>
      <div class="escala">
        <span>0–34</span> clima de cautela<br>
        <span>35–64</span> clima neutro<br>
        <span>65–100</span> clima de empolgação
      </div>
    </div>
  </div>

  <div class="assinatura">
    <span>Escrito por agentes. <b>Auditado por um professor de IA.</b></span>
    <span class="fontes">Índice calculado a partir de Bluesky, Reddit e Google Trends BR</span>
  </div>
</body>
</html>
",
};

const tplName = $json.template;
const data = $json.data || {};
const tpl = TEMPLATES[tplName];
if (!tpl) throw new Error('template desconhecido: "' + tplName + '" (use "selo-hype" ou "termometro")');

let html = tpl;
for (const [k, v] of Object.entries(data)) {
  const safe = String(v).replace(/[&<>]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c]));
  html = html.split('{{' + k + '}}').join(safe);
}

const faltando = html.match(/\{\{\s*[\w.-]+\s*\}\}/g);
if (faltando) throw new Error('placeholders sem valor para "' + tplName + '": ' + [...new Set(faltando)].join(', '));

const endpoint = BROWSERLESS.replace(//$/, '') + '/screenshot' + (TOKEN ? ('?token=' + encodeURIComponent(TOKEN)) : '');
const filename = tplName + '-' + new Date().toISOString().slice(0, 10) + '.png';
return { json: { html, endpoint, filename, template: tplName } };

const item = $input.item;
const fname = $('Injetar template').item.json.filename || 'imagem.png';
if (item.binary && item.binary.data) {
  item.binary.data.fileName = fname;
  item.binary.data.fileExtension = 'png';
  item.binary.data.mimeType = 'image/png';
}
return item;
